public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[] allowed = {'0','1','8','6','9'};
    char[] mapping = new char[10];
    mapping['0'-'0'] = '0';
    mapping['1'-'0'] = '1';
    mapping['8'-'0'] = '8';
    mapping['6'-'0'] = '9';
    mapping['9'-'0'] = '6';
    int half = n / 2;
    boolean odd = (n % 2 == 1);
    char[] halfArr = new char[half];
    // recursion
    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer pos) {
            if (pos == half) {
                // build full string
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < half; i++) sb.append(halfArr[i]);
                if (odd) {
                    for (char mid : new char[]{'0','1','8'}) {
                        sb.append(mid);
                        for (int i = half - 1; i >= 0; i--) {
                            sb.append(mapping[halfArr[i]-'0']);
                        }
                        result.add(sb.toString());
                        sb.setLength(half + 1); // reset to half+1
                    }
                } else {
                    for (int i = half - 1; i >= 0; i--) {
                        sb.append(mapping[halfArr[i]-'0']);
                    }
                    result.add(sb.toString());
                }
                return;
            }
            for (char c : allowed) {
                if (pos == 0 && c == '0' && n > 1) continue; // leading zero not allowed for length>1
                halfArr[pos] = c;
                accept(pos + 1);
            }
        }
    };
    dfs.accept(0);
    // sort result
    java.util.Collections.sort(result);
